WITH filtered AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, CONCAT(status, '/', carrier) status_carrier, ADD_MONTHS(shipped_date, 3) shipped_date_plus_months FROM shipments WHERE order_id IS NOT NULL AND carrier IS DISTINCT FROM 'Kerry') SELECT *, ROW_NUMBER() OVER w_grp row_seq, CUME_DIST() OVER w_part cost_cume_dist FROM filtered WINDOW w_grp AS (PARTITION BY order_id ORDER BY delivered_date, id), w_part AS (PARTITION BY YEAR(delivered_date), order_id ORDER BY cost DESC);
